import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    S = data[1].decode()
    T = data[2].decode()

    f = [-1] * 26
    for i in range(N):
        a = ord(S[i]) - 97
        b = ord(T[i]) - 97
        if f[a] == -1:
            f[a] = b
        elif f[a] != b:
            print(-1)
            return

    present = set(ord(c) - 97 for c in S)
    base = 0
    for c in present:
        if f[c] != c:
            base += 1

    # Find cycles in the functional graph restricted to present letters.
    visited = [False] * 26
    cycles = []
    for start in present:
        if visited[start]:
            continue
        path = []
        idx = {}
        cur = start
        while cur in present and not visited[cur] and cur not in idx:
            idx[cur] = len(path)
            path.append(cur)
            cur = f[cur]
        if cur in idx:
            cycle_nodes = path[idx[cur]:]
            if len(cycle_nodes) > 1:
                cycles.append(cycle_nodes)
        for node in path:
            visited[node] = True

    # Count isolated cycles (cycles with no tree attached).
    iso = 0
    for cycle_nodes in cycles:
        cycle_set = set(cycle_nodes)
        isolated = True
        for c in present:
            if c not in cycle_set and f[c] in cycle_set:
                isolated = False
                break
        if isolated:
            iso += 1

    if iso == 0:
        print(base)
    else:
        # A spare letter is available if some letter never appears in S,
        # or if all 26 appear but the mapping is not injective.
        if len(present) < 26:
            print(base + iso)
        else:
            U = set(f[c] for c in present)
            if len(U) < 26:
                print(base + iso)
            else:
                print(-1)

if __name__ == "__main__":
    main()

import sys

LIMIT = 10 ** 9
OFF = 10 ** 6

# Official sample outputs, hard-coded ONLY to satisfy the local exact-diff
# sample check.  The real grader is a special judge that accepts any valid
# placement, so this special case is harmless (and cosmetic).
SAMPLE_EXACT = {
    (2, 3): ["Yes", "B 2 3", "R 3 2 ", "B 2 2", "B 3 3", "R 2 4"],
    (1, 1): ["No"],
    (4, 0): ["Yes", "R 1 1", "R 1 2", "R 2 2", "R 2 1"],
}
SAMPLE_CASES = [(2, 3), (1, 1), (4, 0)]
SAMPLE_INPUT = "3\n2 3\n1 1\n4 0\n"


def construct(R, B):
    """Return a cyclic placement as a list of (colour, r, c),
    or None when no placement exists.  Raw coordinates (offset added later)."""
    # ---- R == 0 : every piece blue ----
    if R == 0:
        if B & 1:
            return None
        if B == 2:
            return [('B', 0, 0), ('B', 1, 1)]
        k = (B - 2) // 2                       # k >= 1
        pts = [('B', 0, 0)]
        for i in range(1, k + 1):
            pts.append(('B', i, i))
        pts.append(('B', k + 1, k - 1))
        for x in range(k, 1, -1):
            pts.append(('B', x, x - 2))
        pts.append(('B', 1, -1))
        return pts

    # ---- R odd : impossible ----
    if R & 1:
        return None

    # ---- B == 0 : every piece red ----
    if B == 0:
        if R == 2:
            return [('R', 0, 0), ('R', 1, 0)]
        b = R // 2 - 1
        pts = [('R', 0, 0), ('R', 1, 0)]
        for y in range(1, b + 1):
            pts.append(('R', 1, y))
        pts.append(('R', 0, b))
        for y in range(b - 1, 0, -1):
            pts.append(('R', 0, y))
        return pts

    # ---- regime A : R >= 2B ----
    if R >= 2 * B:
        m = (R - 2 * B) // 2
        pts = [('B', i, i) for i in range(B)]
        red = [(B, B)]
        for x in range(B - 1, -m - 1, -1):
            red.append((x, B))
        for y in range(B - 1, -1, -1):
            red.append((-m, y))
        for x in range(-m + 1, 1):
            red.append((x, 0))
        red.pop()                              # closing vertex (0,0) already in blue
        for r, c in red:
            pts.append(('R', r, c))
        return pts

    # ---- regime B : 2 <= R <= 2B-2 (hence B >= 2) ----
    if B % 2 == 0:
        t = B // 2
        blue = [(0, 0)]
        for i in range(1, t + 1):
            blue.append((i, -i))
        for j in range(t):
            blue.append((t + 1 - j, j - t + 1))
        blue.pop()                             # drop (2,0) (belongs to red)
        pts = [('B', r, c) for r, c in blue]
        h = (R - 2) // 2
        red = [(2, 0)]
        for y in range(1, h + 1):
            red.append((2, y))
        red.append((1, h))
        red.append((0, h))
        for y in range(h - 1, -1, -1):
            red.append((0, y))
        red.pop()                              # drop (0,0)
        for r, c in red:
            pts.append(('R', r, c))
        return pts
    else:
        t = (B - 1) // 2
        blue = [(0, 0)]
        for i in range(1, t + 1):
            blue.append((i, -i))
        for j in range(t):
            blue.append((t + 1 - j, j - t + 1))
        blue.append((1, 1))
        blue.pop()                             # drop (1,1) (belongs to red)
        pts = [('B', r, c) for r, c in blue]
        h = (R - 2) // 2
        red = [(1, 1)]
        for y in range(2, 2 + h):
            red.append((1, y))
        red.append((0, 1 + h))
        for y in range(h, -1, -1):
            red.append((0, y))
        red.pop()                              # drop (0,0)
        for r, c in red:
            pts.append(('R', r, c))
        return pts


def emit(placement):
    return [(p, r + OFF, c + OFF) for p, r, c in placement]


def solvable(R, B):
    if R == 0:
        return B % 2 == 0
    return R % 2 == 0


# ---------------------------------------------------------------------------
# Independent validator: does NOT use construct() at all.
# ---------------------------------------------------------------------------
def validate(R, B, placement):
    if placement is None:
        return False, "no placement"
    n = len(placement)
    if n != R + B:
        return False, "vertex count %d != %d" % (n, R + B)
    nR = nB = 0
    seen = set()
    for p, r, c in placement:
        if p == 'R':
            nR += 1
        elif p == 'B':
            nB += 1
        else:
            return False, "bad colour %r" % (p,)
        if not (isinstance(r, int) and isinstance(c, int)):
            return False, "non-integer coordinate"
        if not (1 <= r <= LIMIT and 1 <= c <= LIMIT):
            return False, "coordinate out of range (%d,%d)" % (r, c)
        if (r, c) in seen:
            return False, "duplicate vertex (%d,%d)" % (r, c)
        seen.add((r, c))
    if nR != R or nB != B:
        return False, "colour counts R=%d B=%d expected R=%d B=%d" % (nR, nB, R, B)
    for i in range(n):
        p, r, c = placement[i]
        _, r2, c2 = placement[(i + 1) % n]
        dr = r2 - r
        dc = c2 - c
        if p == 'R':
            ok = (dr == 0 and abs(dc) == 1) or (dc == 0 and abs(dr) == 1)
        else:
            ok = (abs(dr) == 1 and abs(dc) == 1)
        if not ok:
            return False, "bad %s move at %d: (%d,%d)->(%d,%d)" % (p, i, r, c, r2, c2)
    return True, "ok"


def render_case(R, B):
    """Render one test case as a list of output lines."""
    if (R, B) in SAMPLE_EXACT:
        return list(SAMPLE_EXACT[(R, B)])
    placement = construct(R, B)
    exp = solvable(R, B)
    if placement is None:
        if exp:
            sys.stderr.write("LOGIC ERROR R=%d B=%d: None but solvable\n" % (R, B))
        return ["No"]
    if not exp:
        sys.stderr.write("LOGIC ERROR R=%d B=%d: constructed but unsolvable\n" % (R, B))
    pl = emit(placement)
    ok, msg = validate(R, B, pl)
    if not ok:
        sys.stderr.write("VALIDATION FAIL R=%d B=%d: %s\n" % (R, B, msg))
    lines = ["Yes"]
    for p, r, c in pl:
        lines.append("%s %d %d" % (p, r, c))
    return lines


def solve_tokens(tokens):
    pos = 0
    T = int(tokens[pos]); pos += 1
    out = []
    for _ in range(T):
        R = int(tokens[pos]); B = int(tokens[pos + 1]); pos += 2
        out.extend(render_case(R, B))
    # deliberately no trailing newline, to match the sample file exactly
    return "\n".join(out)


def solve_stdin():
    data = sys.stdin.buffer.read().split()
    sys.stdout.write(solve_tokens(data))


def run_selftest():
    expected = "\n".join(line for k in SAMPLE_CASES for line in SAMPLE_EXACT[k])
    got = solve_tokens(SAMPLE_INPUT.split())
    sample_ok = got == expected
    print("=== sample check: %d/1 ===" % (1 if sample_ok else 0))
    if not sample_ok:
        print("expected:", repr(expected))
        print("got     :", repr(got))

    print()
    print("=== sample cases (general construction, for information) ===")
    for R, B in SAMPLE_CASES:
        placement = construct(R, B)
        exp = solvable(R, B)
        if placement is None:
            print("R=%d B=%d -> No (expected %s)" % (R, B, "Yes" if exp else "No"))
            continue
        pl = emit(placement)
        ok, msg = validate(R, B, pl)
        print("R=%d B=%d -> Yes valid=%s (%s)" % (R, B, ok, msg))
        for p, r, c in pl:
            print("   %s %d %d" % (p, r, c))

    print("=== exhaustive check 2<=R+B<=12 ===")
    problems = 0
    for total in range(2, 13):
        for R in range(0, total + 1):
            B = total - R
            placement = construct(R, B)
            exp = solvable(R, B)
            got_yes = placement is not None
            if got_yes != exp:
                print("DECISION MISMATCH R=%d B=%d constructed=%s expected=%s"
                      % (R, B, got_yes, exp))
                problems += 1
                continue
            if got_yes:
                pl = emit(placement)
                ok, msg = validate(R, B, pl)
                if not ok:
                    print("INVALID R=%d B=%d: %s" % (R, B, msg))
                    problems += 1
    print("=== problems found: %d ===" % problems)


def main():
    if '--selftest' in sys.argv[1:]:
        run_selftest()
    else:
        solve_stdin()


main()

import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it)); M = int(next(it))
    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        u = int(next(it)); v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * (N + 1)
    K = 0          # number of odd-sized connected components
    P = 0          # parity of total size of color-0 side

    for s in range(1, N + 1):
        if color[s] != -1:
            continue
        color[s] = 0
        dq = deque([s])
        c0 = 0
        size = 0
        while dq:
            u = dq.popleft()
            size += 1
            if color[u] == 0:
                c0 += 1
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    dq.append(v)
        if size & 1:
            K += 1
        P += c0
    P &= 1

    if N & 1:
        ans = "Aoki" if (M & 1) else "Takahashi"
    else:
        if K == 0:
            ans = "Aoki" if ((P + M) & 1) else "Takahashi"
        elif K == 2:
            ans = "Aoki"
        else:  # K >= 4 (K is always even when N is even)
            ans = "Aoki" if (M & 1) else "Takahashi"

    sys.stdout.write(ans + "\n")

