import random


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    K = int(data[0])
    S = data[1]
    T = data[2]
    n = len(S)
    m = len(T)

    # ---- strip longest common prefix / suffix (invariant for edit distance) ----
    p = 0
    while p < n and p < m and S[p] == T[p]:
        p += 1
    ln = n - p
    lm = m - p
    s = 0
    while s < ln and s < lm and S[n - 1 - s] == T[m - 1 - s]:
        s += 1
    if s:
        S = S[p:n - s]
        T = T[p:m - s]
    else:
        S = S[p:]
        T = T[p:]
    n = len(S)
    m = len(T)

    if n == 0 and m == 0:
        sys.stdout.write("Yes\n")
        return
    if abs(n - m) > K:
        sys.stdout.write("No\n")
        return

    d_star = m - n  # final diagonal j - i

    # ---- rolling hash, modulus 2^61 - 1, random odd base ----
    MOD = (1 << 61) - 1
    BASE = random.randrange(1 << 20, 1 << 40) | 1

    mx = n if n > m else m
    pw = [1] * (mx + 1)
    acc = 1
    for i in range(1, mx + 1):
        acc = acc * BASE % MOD
        pw[i] = acc

    hs = [0] * (n + 1)
    cur = 0
    for i in range(n):
        cur = (cur * BASE + S[i]) % MOD
        hs[i + 1] = cur
    ht = [0] * (m + 1)
    cur = 0
    for i in range(m):
        cur = (cur * BASE + T[i]) % MOD
        ht[i + 1] = cur

    def lcp(i, j):
        # longest common prefix of S[i:] and T[j:]
        a = n - i
        b = m - j
        maxl = a if a < b else b
        if maxl <= 0:
            return 0
        if (hs[i + 1] - hs[i] * BASE) % MOD != (ht[j + 1] - ht[j] * BASE) % MOD:
            return 0
        lo = 1
        while lo * 2 <= maxl:
            L = lo * 2
            if (hs[i + L] - hs[i] * pw[L]) % MOD == (ht[j + L] - ht[j] * pw[L]) % MOD:
                lo = L
            else:
                break
        hi = lo * 2
        if hi > maxl:
            hi = maxl
        while lo < hi:
            mid = (lo + hi + 1) >> 1
            if (hs[i + mid] - hs[i] * pw[mid]) % MOD == (ht[j + mid] - ht[j] * pw[mid]) % MOD:
                lo = mid
            else:
                hi = mid - 1
        return lo

    size = 2 * K + 1
    # V[K+d] = furthest i reachable with <= c edits on diagonal d = j - i
    V = [-1] * size
    V[K] = lcp(0, 0)
    if V[K + d_star] >= n:
        sys.stdout.write("Yes\n")
        return

    for c in range(1, K + 1):
        NV = [-1] * size
        for d in range(-K, K + 1):
            idx = K + d
            best = V[idx]  # use fewer edits (carry)
            # insert into S: predecessor diagonal d-1, i unchanged
            if d - 1 >= -K:
                i0 = V[idx - 1]
                if i0 >= 0:
                    j = i0 + d
                    if 0 <= j <= m:
                        val = i0 + lcp(i0, j)
                        if val > best:
                            best = val
            # delete from S: predecessor diagonal d+1, i+1
            if d + 1 <= K:
                i0 = V[idx + 1]
                if i0 >= 0:
                    i1 = i0 + 1
                    if i1 <= n:
                        j = i1 + d
                        if 0 <= j <= m:
                            val = i1 + lcp(i1, j)
                            if val > best:
                                best = val
            # replace: predecessor diagonal d, i+1
            i0 = V[idx]
            if i0 >= 0:
                i1 = i0 + 1
                if i1 <= n:
                    j = i1 + d
                    if 0 <= j <= m:
                        val = i1 + lcp(i1, j)
                        if val > best:
                            best = val
            NV[idx] = best
        V = NV
        if V[K + d_star] >= n:
            sys.stdout.write("Yes\n")
            return

    sys.stdout.write("No\n")


if __name__ == "__main__":
    solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Precompute maximal run lengths of equal characters.
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j

        def feasible(L: int) -> bool:
            if L == 1:
                # Final string must be strictly alternating: only two targets.
                mism = 0
                for k in range(n):
                    if (ord(s[k]) - 48) != (k & 1):
                        mism += 1
                return min(mism, n - mism) <= numOps

            # For L >= 2, flips go in run interiors so runs are independent.
            # A run of length r needs floor(r / (L + 1)) flips.
            flips = 0
            for r in runs:
                flips += r // (L + 1)
                if flips > numOps:
                    return False
            return True

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo


# ---------------------------------------------------------------------------
# Differential testing harness: brute force vs candidate.
# ---------------------------------------------------------------------------

def longest_run(bits):
    if not bits:
        return 0
    best = cur = 1
    for i in range(1, len(bits)):
        if bits[i] == bits[i - 1]:
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 1
    return best


def brute_table(s):
    """ans[k] = min achievable longest run using AT MOST k flips."""
    n = len(s)
    base = [ord(c) - 48 for c in s]
    INF = float("inf")
    best = [INF] * (n + 1)          # best[k] = min run using EXACTLY k flips
    for mask in range(1 << n):
        k = bin(mask).count("1")
        bits = [base[i] ^ ((mask >> i) & 1) for i in range(n)]
        lr = longest_run(bits)
        if lr < best[k]:
            best[k] = lr
    res = []
    cur = INF
    for k in range(n + 1):
        if best[k] < cur:
            cur = best[k]
        res.append(cur)
    return res


def main():
    sol = Solution()
    mismatches = []
    total = 0

    for n in range(1, 10):
        for m in range(1 << n):
            s = format(m, "0{}b".format(n))
            table = brute_table(s)
            for numOps in range(n + 1):
                total += 1
                cand = sol.minLength(s, numOps)
                ref = table[numOps]
                if cand != ref:
                    mismatches.append((s, numOps, cand, ref))

    print("Total cases tested:", total)
    if mismatches:
        print("MISMATCHES FOUND:", len(mismatches))
        for s, numOps, cand, ref in mismatches[:50]:
            print("  s=%s numOps=%d candidate=%d brute=%d"
                  % (s, numOps, cand, ref))
    else:
        print("ALL MATCH: candidate == brute force over n=1..9, numOps=0..n")

    examples = [("000001", 1, 2), ("0000", 2, 1), ("0101", 0, 1)]
    for s, numOps, expected in examples:
        got = sol.minLength(s, numOps)
        tag = "OK" if got == expected else "FAIL"
        print("Example s=%r numOps=%d -> got %d expected %d [%s]"
              % (s, numOps, got, expected, tag))

    probes = ["0110", "000111", "1110111", "001100",
              "000000", "010", "0011", "0001111"]
    for s in probes:
        table = brute_table(s)
        row = []
        for numOps in range(len(s) + 1):
            cand = sol.minLength(s, numOps)
            ref = table[numOps]
            row.append((numOps, cand, ref, cand == ref))
        ok = all(r[3] for r in row)
        print("Probe s=%r all_ok=%s" % (s, ok))
        print("    " + " ".join("%d:%d/%d" % (n, c, r) for n, c, r, _ in row))


if __name__ == "__main__":
    main()

import sys
import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    H, W, X = data[0], data[1], data[2]
    P, Q = data[3] - 1, data[4] - 1
    vals = data[5:5 + H * W]
    S = [vals[i * W:(i + 1) * W] for i in range(H)]

    occupied = bytearray(H * W)
    start_idx = P * W + Q
    occupied[start_idx] = 1
    cur = S[P][Q]

    heap = []

    if P > 0:
        heapq.heappush(heap, (S[P - 1][Q], P - 1, Q))
    if P + 1 < H:
        heapq.heappush(heap, (S[P + 1][Q], P + 1, Q))
    if Q > 0:
        heapq.heappush(heap, (S[P][Q - 1], P, Q - 1))
    if Q + 1 < W:
        heapq.heappush(heap, (S[P][Q + 1], P, Q + 1))

    while heap:
        val, i, j = heapq.heappop(heap)
        idx = i * W + j

        if occupied[idx]:
            continue

        if X * val < cur:
            occupied[idx] = 1
            cur += val

            if i > 0:
                ni = i - 1
                nidx = ni * W + j
                if not occupied[nidx]:
                    heapq.heappush(heap, (S[ni][j], ni, j))
            if i + 1 < H:
                ni = i + 1
                nidx = ni * W + j
                if not occupied[nidx]:
                    heapq.heappush(heap, (S[ni][j], ni, j))
            if j > 0:
                nj = j - 1
                nidx = i * W + nj
                if not occupied[nidx]:
                    heapq.heappush(heap, (S[i][nj], i, nj))
            if j + 1 < W:
                nj = j + 1
                nidx = i * W + nj
                if not occupied[nidx]:
                    heapq.heappush(heap, (S[i][nj], i, nj))
        else:
            break

    print(cur)


if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        present = [x for x in nums if x <= threshold]
        isolated = n - len(present)

        if not present:
            return isolated

        # Optional fast path: if 1 is present, it connects to every present value.
        if present and 1 in present:
            return 1 + isolated

        m = len(present)
        parent = list(range(m))
        rank = [0] * m

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        # rep[L] is the DSU index of one present divisor of L.
        rep = [-1] * (threshold + 1)

        for idx, d in enumerate(present):
            for L in range(d, threshold + 1, d):
                r = rep[L]
                if r == -1:
                    rep[L] = idx
                else:
                    union(idx, r)

        roots = 0
        for i in range(m):
            if find(i) == i:
                roots += 1

        return roots + isolated
